import React, { useState, useEffect } from 'react';
import Modal, { ModalHeader } from '../components/Modal';
import Calendar from '../components/Calendar';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';

function Stars({ n }) {
  const v = parseFloat(n) || 0;
  return <span><span style={{ color: '#f59e0b' }}>{'★'.repeat(Math.floor(v))}</span><span style={{ color: 'var(--text2)', fontSize: '.8rem' }}> {v.toFixed(1)}</span></span>;
}

export default function ProfModal({ prof, onClose, onReserve }) {
  const { user } = useAuth();
  const [tab, setTab] = useState('profil');
  const [avis, setAvis] = useState([]);
  const [rating, setRating] = useState(0);
  const [comment, setComment] = useState('');
  const [reserving, setReserving] = useState(false);
  const [date, setDate] = useState('');
  const [heure, setHeure] = useState('14:00');

  const profId = prof.prof_id || prof.id;

  useEffect(() => {
    if (tab === 'avis') {
      api.get(`/api/avis/professeur/${profId}`).then(r => setAvis(r.data)).catch(() => setAvis([]));
    }
  }, [tab, profId]);

  async function handleReserve() {
    if (!date) return;
    try {
      await api.post('/api/reservations/', { prof_id: profId, date_cours: date, heure_debut: heure, heure_fin: heure, notes_etudiant: '' });
      alert('✅ Réservation envoyée !');
      setReserving(false);
      onClose();
    } catch (e) {
      alert('Erreur lors de la réservation');
    }
  }

  const profNom = prof.user_nom || prof.nom || 'Professeur';
  const tab_style = (t) => ({ flex: 1, padding: 8, textAlign: 'center', borderRadius: 8, cursor: 'pointer', fontWeight: 600, fontSize: '.82rem', transition: '.2s', background: tab === t ? '#6c63ff' : 'transparent', color: tab === t ? '#fff' : 'var(--text2)' });

  return (
    <Modal onClose={onClose} maxWidth={680}>
      <ModalHeader title="" onClose={onClose} />
      {/* Prof header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 16, marginBottom: 20 }}>
        <div style={{ width: 56, height: 56, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.6rem' }}>👨‍🏫</div>
        <div>
          <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: '1.1rem' }}>{profNom}</div>
          <div style={{ fontSize: '.82rem', color: 'var(--text2)' }}>{prof.matieres?.[0] || prof.matiere} · {prof.ville} · {prof.tarif} DT/h</div>
          <Stars n={prof.note_moyenne} />
        </div>
      </div>

      {/* Tabs */}
      <div style={{ display: 'flex', background: 'var(--surface2)', borderRadius: 12, padding: 4, marginBottom: 20 }}>
        {[['profil','📋 Profil'],['calendrier','📅 Disponibilités'],['avis','⭐ Avis']].map(([t,l]) => (
          <div key={t} style={tab_style(t)} onClick={() => setTab(t)}>{l}</div>
        ))}
      </div>

      {tab === 'profil' && (
        <div>
          {prof.bio && <div style={{ background: 'var(--surface2)', borderRadius: 12, padding: 16, marginBottom: 12 }}>
            <div style={{ fontWeight: 600, marginBottom: 8 }}>📝 À propos</div>
            <div style={{ fontSize: '.875rem', color: 'var(--text2)', lineHeight: 1.6 }}>{prof.bio}</div>
          </div>}
          {prof.diplome && <div style={{ background: 'var(--surface2)', borderRadius: 12, padding: 16, marginBottom: 12 }}>
            <div style={{ fontWeight: 600, marginBottom: 8 }}>🎓 Formation</div>
            <div style={{ fontSize: '.875rem', color: 'var(--text2)' }}>{prof.diplome}</div>
          </div>}
          {(prof.niveaux?.length > 0) && <div style={{ background: 'var(--surface2)', borderRadius: 12, padding: 16, marginBottom: 12 }}>
            <div style={{ fontWeight: 600, marginBottom: 8 }}>🏫 Niveaux enseignés</div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
              {prof.niveaux.map(n => <span key={n} style={{ background: 'rgba(108,99,255,.15)', color: '#6c63ff', fontSize: '.72rem', fontWeight: 600, padding: '2px 8px', borderRadius: 20 }}>{n}</span>)}
            </div>
          </div>}
          <div style={{ display: 'flex', gap: 12, marginTop: 16 }}>
            {user?.role === 'étudiant' && (
              <button onClick={() => setReserving(true)} style={{ flex: 1, padding: '11px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', border: 'none', borderRadius: 10, fontWeight: 600, cursor: 'pointer' }}>📅 Réserver un cours</button>
            )}
          </div>
          {reserving && (
            <div style={{ marginTop: 20, background: 'var(--surface2)', borderRadius: 12, padding: 20 }}>
              <div style={{ fontWeight: 600, marginBottom: 16 }}>📅 Choisir un créneau</div>
              <div style={{ marginBottom: 12 }}>
                <label style={{ fontSize: '.82rem', color: 'var(--text2)', display: 'block', marginBottom: 6 }}>Date</label>
                <input type="date" value={date} onChange={e => setDate(e.target.value)} style={{ background: 'var(--bg)', border: '1px solid var(--border)', borderRadius: 8, color: 'var(--text)', padding: '8px 12px', width: '100%' }} />
              </div>
              <div style={{ marginBottom: 16 }}>
                <label style={{ fontSize: '.82rem', color: 'var(--text2)', display: 'block', marginBottom: 6 }}>Heure</label>
                <select value={heure} onChange={e => setHeure(e.target.value)} style={{ background: 'var(--bg)', border: '1px solid var(--border)', borderRadius: 8, color: 'var(--text)', padding: '8px 12px', width: '100%' }}>
                  {['08:00','09:00','10:00','11:00','14:00','15:00','16:00','17:00','18:00'].map(h => <option key={h}>{h}</option>)}
                </select>
              </div>
              <div style={{ display: 'flex', gap: 10 }}>
                <button onClick={() => setReserving(false)} style={{ flex: 1, padding: '9px', background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 8, color: 'var(--text)', cursor: 'pointer' }}>Annuler</button>
                <button onClick={handleReserve} style={{ flex: 2, padding: '9px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', border: 'none', borderRadius: 8, fontWeight: 600, cursor: 'pointer' }}>✅ Confirmer</button>
              </div>
            </div>
          )}
        </div>
      )}

      {tab === 'calendrier' && (
        <div>
          <Calendar available={[5,8,11,13,15,20,22,27]} booked={[4,10,16,21]} />
          {user?.role === 'étudiant' && (
            <button onClick={() => { setTab('profil'); setReserving(true); }} style={{ marginTop: 16, width: '100%', padding: '11px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', border: 'none', borderRadius: 10, fontWeight: 600, cursor: 'pointer' }}>
              📅 Réserver ce professeur
            </button>
          )}
        </div>
      )}

      {tab === 'avis' && (
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 20, marginBottom: 20, padding: 16, background: 'var(--surface2)', borderRadius: 12 }}>
            <div style={{ textAlign: 'center' }}>
              <div style={{ fontFamily: 'Syne', fontSize: '2.5rem', fontWeight: 800 }}>{parseFloat(prof.note_moyenne || 0).toFixed(1)}</div>
              <Stars n={prof.note_moyenne} />
              <div style={{ fontSize: '.75rem', color: 'var(--text2)', marginTop: 4 }}>{prof.nb_avis} avis</div>
            </div>
            <div style={{ flex: 1 }}>
              {[5,4,3,2,1].map(s => (
                <div key={s} style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
                  <span style={{ fontSize: '.75rem', width: 20 }}>{s}★</span>
                  <div style={{ flex: 1, height: 6, background: 'var(--border)', borderRadius: 3, overflow: 'hidden' }}>
                    <div style={{ height: '100%', background: '#f59e0b', borderRadius: 3, width: `${s === 5 ? 70 : s === 4 ? 20 : s === 3 ? 7 : 2}%` }} />
                  </div>
                </div>
              ))}
            </div>
          </div>

          {avis.map(a => (
            <div key={a.id} style={{ background: 'var(--surface2)', borderRadius: 12, padding: 16, marginBottom: 12 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8 }}>
                <div style={{ fontWeight: 600, fontSize: '.88rem' }}>{a.etudiant}</div>
                <div style={{ color: '#f59e0b' }}>{'★'.repeat(a.note)}</div>
              </div>
              <div style={{ fontSize: '.875rem', color: 'var(--text2)', lineHeight: 1.55 }}>{a.commentaire}</div>
            </div>
          ))}

          {avis.length === 0 && <div style={{ textAlign: 'center', padding: 30, color: 'var(--text2)', fontSize: '.85rem' }}>Aucun avis pour ce professeur.</div>}
        </div>
      )}
    </Modal>
  );
}
